<?php require 'includes/bootstrap.php';if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();$action=$_POST['action']??'';$id=(int)($_POST['id']??0);if($action==='clear'){unset($_SESSION['cart']);}elseif($id>0){$s=$pdo->prepare('SELECT stock FROM products WHERE id=?');$s->execute([$id]);$stock=$s->fetchColumn();if($stock!==false){$qty=($action==='add'?($_SESSION['cart'][$id]??0)+1:($action==='remove'?0:(int)($_POST['quantity']??0)));$qty=max(0,min($qty,(int)$stock));if($qty)$_SESSION['cart'][$id]=$qty;else unset($_SESSION['cart'][$id]);}}header('Location: cart.php');exit;}$items=cartDetails($pdo);$total=array_sum(array_column($items,'line_total'));$pageTitle='Your Cart | AquaPure';require 'includes/header.php';?><section class="container page"><div class="section-head"><div><span class="eyebrow">YOUR SELECTION</span><h1>Your shopping cart</h1><p>Review your water order before checkout.</p></div></div><?php if(!$items):?><div class="empty">🛒<h2>Your cart is empty</h2><p>Fresh water is just a click away.</p><a class="btn" href="index.php#products">Browse Water →</a></div><?php else:?><div class="cart-layout"><div class="cart-items"><?php foreach($items as $p):?><div class="cart-item"><div class="mini-icon">💧</div><div class="item-info"><h3><?=e($p['name'])?></h3><small><?=money($p['price'])?> each</small></div><form method="post" class="quantity"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="update"><input type="hidden" name="id" value="<?=$p['id']?>"><input aria-label="Quantity" type="number" name="quantity" min="0" max="<?=$p['stock']?>" value="<?=$p['quantity']?>"><button class="small-btn">Update</button></form><strong><?=money($p['line_total'])?></strong><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="remove"><input type="hidden" name="id" value="<?=$p['id']?>"><button class="remove" title="Remove">×</button></form></div><?php endforeach;?></div><aside class="summary"><h2>Order summary</h2><div class="total-row"><span>Subtotal</span><strong><?=money($total)?></strong></div><p class="muted">Delivery arrangements and any delivery fee will be confirmed separately.</p><div class="total-row grand"><span>Total (items)</span><strong><?=money($total)?></strong></div><a class="btn full" href="checkout.php">Proceed to Checkout →</a><a class="back" href="index.php#products">← Continue shopping</a></aside></div><?php endif;?></section><?php require 'includes/footer.php';?>
